const val APP_VERSION="Deep_Timeline_v20261111T141738Z"
val BILLION:BigInteger=BigInteger.valueOf(1000000000L)
val DAY_SECONDS=86400.0
val MONTH_SECONDS=29.530588853*DAY_SECONDS
val YEAR_SECONDS=365.24274*DAY_SECONDS
data class Moment(val second:Long,val nano:Int):Comparable<Moment>{override fun compareTo(other:Moment):Int{val s=second.compareTo(other.second);return if(s!=0)s else nano.compareTo(other.nano)};fun total():BigInteger=BigInteger.valueOf(second).multiply(BILLION).add(BigInteger.valueOf(nano.toLong()));fun utc():String=Instant.ofEpochSecond(second,nano.toLong()).toString();fun shift(nanoseconds:BigInteger):Moment=fromTotal(total().add(nanoseconds));companion object{fun now():Moment{val i=Instant.now();return Moment(i.epochSecond,i.nano)};fun fromTotal(v:BigInteger):Moment{val qr=v.divideAndRemainder(BILLION);val q=if(qr[1].signum()<0)qr[0].subtract(BigInteger.ONE) else qr[0];val r=if(qr[1].signum()<0)qr[1].add(BILLION) else qr[1];return Moment(q.longValueExact(),r.toInt())}}}
data class TimelineEvent(val id:String=UUID.randomUUID().toString(),val title:String,val moment:Moment,val civil:String,val mode:String,val coords:String,val zone:String,val offsetNano:String,val created:Long=System.currentTimeMillis(),val updated:Long=System.currentTimeMillis(),val maxScaleAmount:String="",val maxScaleUnit:String="DAY")
object TimeMath{fun parseCivil(date:String,time:String):LocalDateTime{val parts=Regex("^([+-]?\\d{1,12})-(\\d{1,2})-(\\d{1,2})$").matchEntire(date.trim())?:throw IllegalArgumentException("Date format: YYYY-MM-DD, or -YYYY-MM-DD for BCE");val raw=parts.groupValues[1];val year=raw.toIntOrNull()?:throw IllegalArgumentException("Year outside supported range");require(year!=0){"No year zero: use -1 for 1 BCE and 1 for 1 CE"};val astronomical=if(year<0)year+1 else year;val month=parts.groupValues[2].toInt();val day=parts.groupValues[3].toInt();val clock=try{LocalTime.parse(time.trim(),DateTimeFormatter.ISO_LOCAL_TIME)}catch(_:Exception){throw IllegalArgumentException("Time format: HH:MM[:SS[.nnnnnnnnn]]")};return LocalDateTime.of(astronomical,month,day,clock.hour,clock.minute,clock.second,clock.nano)}
fun formatCivil(civil:LocalDateTime):String{val year=if(civil.year<=0)civil.year-1 else civil.year;val digits=if(year<0)"-"+(-year.toLong()).toString().padStart(4,'0') else if(year>9999)"+"+year.toString() else year.toString().padStart(4,'0');return "$digits-${civil.monthValue.toString().padStart(2,'0')}-${civil.dayOfMonth.toString().padStart(2,'0')}T${civil.toLocalTime()}"}
fun fromUtc(civil:LocalDateTime):Moment{val i=civil.toInstant(ZoneOffset.UTC);return Moment(i.epochSecond,i.nano)};fun fromLongitude(civil:LocalDateTime,longitude:BigDecimal):Pair<Moment,String>{require(longitude>=BigDecimal("-180")&&longitude<=BigDecimal("180")){"Longitude must be between -180 and 180"};val offset=longitude.multiply(BigDecimal("240000000000")).setScale(0,RoundingMode.HALF_UP).toBigIntegerExact();return Pair(fromUtc(civil).shift(offset.negate()),offset.toString())};fun fromLocal(civil:LocalDateTime,zoneName:String):Pair<List<Pair<Moment,String>>,String>{val zone=ZoneId.of(zoneName);val offsets=zone.rules.getValidOffsets(civil);if(offsets.isEmpty())return Pair(emptyList(),"The selected local time does not exist due to a clock change");return Pair(offsets.map{val i=civil.toInstant(it);Pair(Moment(i.epochSecond,i.nano),it.toString())},"")};fun deltaSeconds(a:Moment,b:Moment):Double{val s=try{Math.subtractExact(a.second,b.second).toDouble()}catch(_:ArithmeticException){BigInteger.valueOf(a.second).subtract(BigInteger.valueOf(b.second)).toDouble()};return s+(a.nano-b.nano)/1000000000.0};fun screenY(at:Moment,center:Moment,secondsPerPixel:Double,height:Int):Double=height/2.0+deltaSeconds(at,center)/secondsPerPixel;fun halfDistance(a:Moment,b:Moment):BigInteger=a.total().subtract(b.total()).abs();fun pan(moment:Moment,deltaSeconds:Double):Moment{if(!deltaSeconds.isFinite())return moment;return try{moment.shift(BigDecimal.valueOf(deltaSeconds).multiply(BigDecimal("1000000000")).setScale(0,RoundingMode.HALF_EVEN).toBigInteger())}catch(_:Exception){moment}}}
object Coordinates{fun parse(raw:String):Pair<BigDecimal,BigDecimal>{val t=raw.trim().replace("°","").replace(";",",");val parts=if(t.contains(','))t.split(',').map{it.trim()} else t.split(Regex("\\s+")).filter{it.isNotEmpty()};require(parts.size==2){"Enter latitude, longitude (for example 39.7392, -104.9903)"};fun number(token:String,lat:Boolean):BigDecimal{var p=token.trim().uppercase();var sign=1;val h=p.firstOrNull();if(h=='N'||h=='S'||h=='E'||h=='W'){if(h=='S'||h=='W')sign=-1;p=p.drop(1).trim()};val tail=p.lastOrNull();if(tail=='N'||tail=='S'||tail=='E'||tail=='W'){if(tail=='S'||tail=='W')sign=-1;p=p.dropLast(1).trim()};val v=p.toBigDecimal().multiply(BigDecimal.valueOf(sign.toLong()));require(v>=BigDecimal(if(lat)"-90" else "-180")&&v<=BigDecimal(if(lat)"90" else "180")){"Coordinate outside valid range"};return v};return Pair(number(parts[0],true),number(parts[1],false))}}
object LabelSolver{fun solve(anchors:DoubleArray,gap:Double,origin:Double=0.0):DoubleArray{val n=anchors.size;if(n==0)return DoubleArray(0);require(gap>0.0&&gap.isFinite()&&origin.isFinite());for(i in anchors.indices)require(anchors[i].isFinite()&&(i==0||anchors[i]>=anchors[i-1]));fun lowerBound(value:Double):Int{var lo=0;var hi=n;while(lo<hi){val mid=(lo+hi) ushr 1;if(anchors[mid]<value)lo=mid+1 else hi=mid};return lo};fun upperBound(value:Double):Int{var lo=0;var hi=n;while(lo<hi){val mid=(lo+hi) ushr 1;if(anchors[mid]<=value)lo=mid+1 else hi=mid};return lo};fun pack(start:Int,end:Int):DoubleArray{val result=DoubleArray(n);val middle=(start+end)*0.5;for(i in start..end)result[i]=anchors[start]+(i-middle)*gap;for(i in start-1 downTo 0)result[i]=min(anchors[i],result[i+1]-gap);for(i in end+1 until n)result[i]=max(anchors[i],result[i-1]+gap);return result};if(origin<=anchors[0])return pack(0,upperBound(anchors[0])-1);if(origin>=anchors[n-1])return pack(lowerBound(anchors[n-1]),n-1);val right=lowerBound(origin);if(right<n&&anchors[right]==origin)return pack(right,upperBound(origin)-1);val left=right-1;val first=pack(lowerBound(anchors[left]),left);val second=pack(right,upperBound(anchors[right])-1);val t=((origin-anchors[left])/(anchors[right]-anchors[left])).coerceIn(0.0,1.0);val smooth=t*t*(3.0-2.0*t);return DoubleArray(n){first[it]+(second[it]-first[it])*smooth}}}
